   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“灭火计划”失败了，你打破了不应该打破的那扇大门。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="明明只要回头就不会有事，为什么还是止不住你的好奇心，进来了呢？", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你真是……病入膏肓。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ板着脸严厉地开口，可刚说完，他立刻露出了无奈却又饱含着欣慰的灿烂笑容。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你一路走来，想必看到了很多惨剧，也产生了很多怀疑。下面，我会为你们一一解答。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="除开神光重科科研主任以外，我还有另一个身份——一名并不入流的吟游诗人。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ打了个响指，明快的乐曲从装置中播放了出来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在极北被封锁的那些漫长极夜里，每当大家陷入精神低迷时，我会让他们陪着我坐在窗边，守着虚蚀域的天空，听我讲述从祖辈那里传下来的神话故事——", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="关于伯基索米的黄金时代，那些在冰原上开辟航道的先民乘着帆船，横渡大海追寻星辰的故事。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ弯起了嘴角，这是他第一次露出笑容。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="众多神话传说中，学生们最喜欢的，是关于一头龙的故事。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="巨龙没有金色的鳞片，不会喷吐烈焰，\n翅膀像炭一样黑，眼睛却如最耀眼的星辰一样明亮。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="祂点燃了自己的身体，绕着地平线飞行，\n将光与热播撒在这片冰海，为其带来了生命。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="绕行一圈后，\n巨龙会沉入地平线之下，载着亡者的魂灵回归大地，\n直到安抚完所有逝者后才会再度起飞。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="祂从不休息，\n因为它知道，如果它停下来，\n冰海就会永远冻结，\n其上的生灵会永远迷失方向。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="其名为——“太阳赫梅克”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们所有人都转头看向了赫梅克，而她则目不转睛地盯着面前的人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尽管自己的名字与Ђ主任并无关联，但她仍有一种冥冥之中与他同处一个时空的亲切感。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他站在几十年前的过去，而她站在他之后的未来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在这漫漫长夜中，粮食越来越少，研究也陷入了僵局。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们时常围坐在一起，相互编纂和讲述“太阳神赫梅克”的故事。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="祂的故事为我们带来了温暖，驱逐心中的麻木与畏惧……每当这时，我们便会欢笑，会说胡话，甚至嚎啕大哭……", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [85]={next_id=86, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我相信……祂是存在的……祂一定在不知何处看着我们……", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他笑了笑，那笑容里有一种让人心碎的温柔，他的声音越来越轻，像是在念一首古老的歌谣。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然后，他收起了笑容，神情变得极为严肃。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="接下来我要告诉你们的是，有关我的发现。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我在录像中说了谎，实际上我在神光重科发现这段频率时，我已经通过物理手段，几乎让它稳定复现。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们沉浸在复现的成功中，将要去解析它的时候，却没有发现危险悄然而至。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那段频率有着极强的穿透力，它穿过了我们的层层防护措施跑到了实验室之外。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而恰好此时，大统领在我们的城市进行考察，这段频率对她产生了极为严重的影响。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ主任再一次提起了大统领，你却感觉四周都变得冷了下来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在我发现这个关联之后不久，我的项目组就被列入了“肃清”名单，我被迫带着所有的资料和学生们一起远渡重洋，来到虚蚀域。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我不知道这段频率和大统领之间是什么关系。但我想，大统领不想让任何人知道它的存在。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，在制定“灭火计划”的过程中，我说出了我的顾虑，而我的学生们也欣然为我保留了这份可能性。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们设置了隐晦的线索，以及引来修格尔的信号发射器，以此作为重重考验。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="做完这一切，我将我的胸针交予了一位最后的朋友。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不知为何，你感到Ђ看向了赫梅克，露出了怀念的表情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那是一位自百年战争结束后便在虚蚀域奋战至今的战士，她是前些日子才来到科学院的。她说自己命不久矣，在寻找自己的葬身之处。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我将胸针交给了她，希望她能在临死之前将其送到伯基索米，送到神光重科之内。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_15_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
