   [237]={next_id=238, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克指了指自己愣在原地。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [238]={next_id=239, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="殿下，我只会和修格尔战斗，你让我唱歌……实在是强人所难。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [239]={next_id=240, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="别急着拒绝。弦枝说，这首歌你肯定会唱。而且，比任何人都熟悉。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [240]={next_id=241, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克疑惑地看着你，弦枝则拿出了乐琴，向赫梅克招招手。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [241]={next_id=242, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她拉着赫梅克，指着乐谱教给她怎么辨认。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [242]={next_id=243, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="起初她只是随意地扫了一眼。但仅仅过了两秒，她整个人如同被雷击中一般，死死地定在了原地。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [243]={next_id=244, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这……这是……", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [244]={next_id=245, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="确实是……我非常熟悉的曲子……", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [245]={next_id=246, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她目光颤动，看着乐谱上的歌词——那是曾经陪伴她成长的船长，亲自交给她唱的歌谣，是她名字的来源。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [246]={next_id=247, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她在这片冰原上杀戮多年，以为自己早已被这个世界遗弃。但现在——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [247]={next_id=248, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一个百年前把她推向大海让她活下去的船长，和一个在百年前毁了退路只为留下真相的科学家……两个毫不相干的人，竟然通过一首歌，在此刻交汇在一起。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [248]={next_id=249, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那就拜托了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [249]={next_id=250, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就当是……为了纪念你的新生，也……为了记住你的那位恩人，向她做一次真正的道别。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [250]={next_id=251, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她死死地捏着那张羊皮纸。然后，她深吸了一口气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
