   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="快点，别磨蹭。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [256]={next_id=257, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不能只让你看我出丑，送上门的把柄我可不会放过。", msg_color="", msg_size=0, talker="尤加利", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [257]={next_id=258, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="请不要在意尤加利，她其实和我们一样，期待赫梅克小姐的歌声。", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [258]={next_id=259, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="红叶微笑不语，只是用鼓励的眼神看着她", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [259]={next_id=260, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在众人热切的注视下，这位面色冷硬的虚蚀猎人竟然罕见地后退了半步，窘迫地在你身后躲了躲。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [260]={next_id=261, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="拎着斧头手撕领主的时候怎么没见你这么扭捏，都是自己人，就别推辞了，队长。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [261]={next_id=262, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你不厚道地一把将她从背后拽了出来，戏谑地推到中央。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [262]={next_id=263, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="被推到聚光灯下，赫梅克无奈地叹了口气，脸颊罕见地飘起了一丝微红。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [263]={next_id=264, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="咳咳。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [264]={next_id=265, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="知道自己退无可退了，赫梅克这才清清嗓子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [265]={next_id=266, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="各位照顾了我这么多，我确实应该感谢大家。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [266]={next_id=267, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这首歌……是黄金时代的水手们在黄金航道上航行时的歌，也是我的过去……我的来时路。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [267]={next_id=268, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她看向弦枝，吟游诗人会意，轻轻拨动琴弦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [268]={next_id=269, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克和着那跨越了百年的节拍，微微张开嘴唇。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [269]={next_id=270, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="起初，她的声音还有些干涩与迟疑，但随着第一个音符吐出，那股融化在血液里的熟悉感瞬间接管了一切。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [270]={next_id=271, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她那略带沙哑的歌声，在无垠的天空和深邃的冰海之间，久久地回荡开来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [271]={next_id=272, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="拉动绳索，摇晃船桨，\n告别家人，背井离乡，\n扬起风帆，向着一无所知的前方。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [272]={next_id=273, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="水手们！起航！起航！\n我们齐心协力，向着太阳高悬的远方！\n我们终将停泊，在那世界的终结之所。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
