   [274]={next_id=275, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="水手们！起航！起航！\n我们直面恐惧，向着幽寒深渊的彼方！\n我们放声高歌，在这万劫不复的航向！", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
